import numpy as np
import ast

def task_func(csv_file):
    data = pd.read_csv(csv_file)

    def parse_list(value):
        if isinstance(value, list):
            return value
        try:
            parsed = ast.literal_eval(value)
        except (ValueError, SyntaxError) as exc:
            raise ValueError(f"Invalid list value: {value!r}") from exc
        if not isinstance(parsed, (list, tuple, np.ndarray)):
            raise ValueError(f"Expected a list, got: {type(parsed).__name__}")
        return list(parsed)

    result = pd.DataFrame({
        "email": data["email"],
        "list": data["list"].map(parse_list),
    })

    result["sum"] = result["list"].map(np.sum)
    result["mean"] = result["list"].map(
        lambda values: np.mean(values) if values else np.nan
    )
    result["std"] = result["list"].map(
        lambda values: np.std(values) if values else np.nan
    )

    ax = sns.histplot(data=result, x="mean")

    return result[["email", "list", "sum", "mean", "std"]], ax

