import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(
    df,
    fruits=None,
    days=None,
    seed=None,
    sales_lower_bound=1,
    sales_upper_bound=50,
):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError(
            "'sales_lower_bound' must be less than 'sales_upper_bound'"
        )

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]

    if days is None:
        days = 7

    if isinstance(days, int):
        if days < 0:
            raise ValueError("'days' must be non-negative")
        day_values = range(days)
    else:
        day_values = days

    fruit_values = list(fruits)
    day_values = list(day_values)

    rng = np.random.default_rng(seed)
    combinations = list(itertools.product(fruit_values, day_values))

    start_date = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    rows = []

    for index, (fruit, day) in enumerate(combinations):
        if isinstance(day, (int, np.integer)):
            date = start_date + timedelta(days=int(day))
        else:
            date = day

        rows.append(
            {
                "Fruit": fruit,
                "Date": date,
                "Sales": rng.integers(
                    sales_lower_bound,
                    sales_upper_bound,
                ),
            }
        )

    sales_df = pd.DataFrame(rows, columns=["Fruit", "Date", "Sales"])
    result_df = pd.concat([df.copy(), sales_df], ignore_index=True)

    plot = sns.catplot(
        data=result_df,
        x="Fruit",
        y="Sales",
        kind="box",
    )

    return result_df, plot

