import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    if not str(file_path).lower().endswith(".csv"):
        raise ValueError("The input file must have a .csv extension.")

    try:
        with open(file_path, mode="r", newline="", encoding="utf-8") as csv_file:
            reader = csv.reader(csv_file, strict=True)
            rows = list(reader)
    except (csv.Error, UnicodeError) as exc:
        raise ValueError("The file is not a properly formatted CSV file.") from exc

    if rows:
        row_length = len(rows[0])
        if any(len(row) != row_length for row in rows):
            raise ValueError("All CSV rows must contain the same number of fields.")

    row_counts = Counter(tuple(row) for row in rows)
    duplicate_counts = {
        row: count for row, count in row_counts.items() if count > 1
    }

    duplicate_df = pd.DataFrame(
        {
            "row": [", ".join(row) for row in duplicate_counts],
            "count": list(duplicate_counts.values()),
        }
    )

    _, ax = plt.subplots()
    duplicate_df.plot(
        kind="bar",
        x="row",
        y="count",
        ax=ax,
        legend=False,
        title="Duplicate CSV Rows",
    )
    ax.set_xlabel("Row")
    ax.set_ylabel("Count")
    plt.tight_layout()

    return duplicate_counts, ax

