import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    decoded_data = base64.b64decode(raw_string).decode("utf-8")
    data = json.loads(decoded_data)

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    def csv_value(value):
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return value

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)

        if isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                fieldnames = []
                for item in data:
                    for key in item:
                        if key not in fieldnames:
                            fieldnames.append(key)

                writer.writerow(fieldnames)
                for item in data:
                    writer.writerow([csv_value(item.get(key, "")) for key in fieldnames])
            elif data and all(isinstance(item, (list, tuple)) for item in data):
                writer.writerows(
                    [[csv_value(value) for value in row] for row in data]
                )
            else:
                for item in data:
                    writer.writerow([csv_value(item)])
        elif isinstance(data, dict):
            writer.writerow(list(data.keys()))
            writer.writerow([csv_value(value) for value in data.values()])
        else:
            writer.writerow([csv_value(data)])

    return file_path

import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    rows = []

    for segment in s.splitlines():
        segment = segment.strip()
        if not segment:
            continue

        parts = re.split(r"\s+", segment, maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                "Each input segment must contain ID, quantity, code, price, and description."
            )

        item_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        rows.append(
            {
                "ID": item_id,
                "Quantity": int(quantity),
                "Code": code,
                "Price": int(price),
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(rows, columns=columns)

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size < 0 or subset_size > len(elements) or subset_size == 0:
        return 1, Series(dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    current_pid = os.getpid()
    pids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/fo", "csv", "/nh"],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                fields = [field.strip('"') for field in line.split('","')]
                if len(fields) >= 2 and fields[0].lower() == process_name.lower():
                    try:
                        pid = int(fields[1])
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) == 2 and parts[1] == process_name:
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0
    for pid in set(pids):
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except OSError:
            pass

    if stopped:
        time.sleep(1)

    return stopped

