import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    source_files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    for file_path in source_files:
        filename = os.path.basename(file_path)
        compressed_path = file_path + ".gz"

        try:
            process = subprocess.Popen(
                ["gzip", file_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
            )
            _, stderr = process.communicate()

            if process.returncode != 0:
                failed_files.append(filename)
                continue

            if not os.path.isfile(compressed_path):
                failed_files.append(filename)
                continue

            shutil.move(compressed_path, os.path.join(dst_folder, os.path.basename(compressed_path)))

        except (OSError, subprocess.SubprocessError, shutil.Error):
            failed_files.append(filename)

    success = not failed_files
    if success:
        message = "All files were compressed and moved successfully."
    else:
        message = f"{len(failed_files)} file(s) failed to compress or move."

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

