import pandas as pd
from random import randint, seed

def task_func(dictionary, item, sample_size=None, random_seed=None):
    """
    Convert a dictionary to a DataFrame and find positions containing item.

    Returns:
        tuple: (list of (row_index, column_name) positions, DataFrame)
    """
    if sample_size is not None:
        if not isinstance(sample_size, int) or isinstance(sample_size, bool):
            raise TypeError("sample_size must be a non-negative integer")
        if sample_size < 0:
            raise ValueError("sample_size must be non-negative")

    dataframe = pd.DataFrame(dictionary)
    positions = []

    for column in dataframe.columns:
        for row_index, value in dataframe[column].items():
            try:
                matches = value == item
                if bool(matches):
                    positions.append((row_index, column))
            except (TypeError, ValueError):
                continue

    if sample_size is not None:
        if sample_size > len(positions):
            raise ValueError("sample_size cannot exceed the number of positions")

        if random_seed is not None:
            seed(random_seed)

        sampled_positions = []
        remaining_positions = positions.copy()

        while len(sampled_positions) < sample_size:
            index = randint(0, len(remaining_positions) - 1)
            sampled_positions.append(remaining_positions.pop(index))

        positions = sampled_positions

    return positions, dataframe

