import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    def get_cpu_usage():
        if platform.system() == "Windows":
            output = subprocess.check_output(
                ["wmic", "cpu", "get", "loadpercentage"]
            ).decode(errors="replace")

            for line in output.splitlines():
                value = line.strip()
                if value.isdigit():
                    return float(value)

            raise RuntimeError("Unable to determine CPU usage")

        output = subprocess.check_output(["top", "-bn1"]).decode(errors="replace")

        for line in output.splitlines():
            if "cpu" not in line.lower():
                continue

            tokens = (
                line.replace(",", " ")
                .replace(":", " ")
                .replace("%", " ")
                .split()
            )

            for index, token in enumerate(tokens):
                if token.lower() in {"id", "idle"} and index > 0:
                    try:
                        return 100.0 - float(tokens[index - 1])
                    except ValueError:
                        continue

        raise RuntimeError("Unable to determine CPU usage")

    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage_percentage": get_cpu_usage(),
            }
        )
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

