def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data is empty or invalid.")

    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("JSON data is corrupted or invalid.")

    current = data

    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect_numeric(value):
        if isinstance(value, bool):
            return
        if isinstance(value, (int, float)):
            if np.isfinite(value):
                values.append(value)
            return
        if isinstance(value, list):
            for item in value:
                collect_numeric(item)
            return
        if isinstance(value, dict):
            for item in value.values():
                collect_numeric(item)

    collect_numeric(current)

    if not values:
        raise ValueError("No numeric data found.")

    fig, ax = plt.subplots()
    sns.boxplot(y=np.asarray(values, dtype=float), ax=ax)
    ax.set_ylabel("Value")
    ax.set_title("Boxplot of Numeric Data")
    fig.tight_layout()

    return fig

