import numpy as np
import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding


def task_func(num, from_base, to_base, private_key, alphabet):
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Bases must be between 2 and 36.")

    value_text = str(num).strip()
    if not value_text:
        raise ValueError("The number cannot be empty.")

    negative = value_text.startswith("-")
    if negative:
        value_text = value_text[1:]

    value = int(value_text, from_base)

    if value == 0:
        converted = "0"
    else:
        result = []
        while value:
            value, remainder = divmod(value, to_base)
            result.append(digits[remainder])
        converted = "".join(reversed(result))

    if negative and converted != "0":
        converted = "-" + converted

    signature = private_key.sign(
        converted.encode("utf-8"),
        padding.PKCS1v15(),
        hashes.SHA256(),
    )

    standard_alphabet = (
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    )
    custom_alphabet = (
        alphabet.decode("ascii") if isinstance(alphabet, bytes) else str(alphabet)
    )

    if len(custom_alphabet) != 64 or len(set(custom_alphabet)) != 64:
        raise ValueError("The custom alphabet must contain 64 unique characters.")

    encoded = base64.b64encode(signature).decode("ascii")
    return encoded.translate(str.maketrans(standard_alphabet, custom_alphabet))

import re
import socket


def task_func(ip_addresses: list) -> dict:
    result = {}
    ip_pattern = re.compile(r"^[0-9A-Fa-f:.]+$")

    for ip_address in ip_addresses:
        if not isinstance(ip_address, str) or not ip_pattern.fullmatch(ip_address):
            continue

        is_valid = False
        for family in (socket.AF_INET, socket.AF_INET6):
            try:
                socket.inet_pton(family, ip_address)
                is_valid = True
                break
            except (OSError, ValueError):
                continue

        if not is_valid:
            continue

        try:
            result[ip_address] = socket.gethostbyaddr(ip_address)[0]
        except (OSError, socket.timeout):
            result[ip_address] = None

    return result

import numpy as np
from sympy import symbols, solve


def task_func(precision=2, seed=0):
    np.random.seed(seed)

    a, b, c = np.random.randint(-10, 11, size=3)
    while a == 0:
        a = np.random.randint(-10, 11)

    x = symbols("x")
    solutions = solve(a * x**2 + b * x + c, x)

    result = []
    for solution in solutions:
        value = complex(solution.evalf())
        result.append(
            complex(
                round(value.real, precision),
                round(value.imag, precision),
            )
        )

    return tuple(result)

