TARGET_VALUES = np.array([1, 3, 4])


def task_func(df):
    cleaned_df = df.copy()

    for column in cleaned_df.columns:
        cleaned_df[column] = cleaned_df[column].where(
            cleaned_df[column].isin(TARGET_VALUES), 0
        )

    transformed_df = cleaned_df.copy()

    for column in transformed_df.columns:
        values = transformed_df[column].to_numpy(dtype=float)

        if values.size == 0 or np.all(values == values[0]):
            transformed_df[column] = values
        else:
            transformed_df[column] = stats.boxcox(values + 1)[0]

    n_columns = len(transformed_df.columns)
    if n_columns == 0:
        figure, _ = plt.subplots()
    else:
        figure, axes = plt.subplots(
            n_columns,
            1,
            figsize=(8, max(4, 3 * n_columns)),
            squeeze=False,
        )
        axes = axes.ravel()

        for axis, column in zip(axes, transformed_df.columns):
            values = transformed_df[column].dropna()

            if len(values) > 1 and not np.all(values == values.iloc[0]):
                values.plot.kde(ax=axis)
            else:
                axis.axvline(
                    values.iloc[0] if len(values) else 0,
                    color="tab:blue",
                )

            axis.set_title(f"KDE of {column}")
            axis.set_xlabel("Transformed value")
            axis.set_ylabel("Density")

        figure.tight_layout()

    return transformed_df, figure

import cgi
import http.server
import json


def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json(self, status_code, payload):
            response = json.dumps(payload).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(response)))
            self.end_headers()
            self.wfile.write(response)

        def do_POST(self):
            content_type = self.headers.get("Content-Type", "")
            media_type, _ = cgi.parse_header(content_type)

            if media_type != "application/json":
                self._send_json(
                    400,
                    {
                        "status": "error",
                        "message": "Content-Type header is not application/json",
                    },
                )
                return

            try:
                content_length = int(self.headers.get("Content-Length", 0))
                body = self.rfile.read(content_length)
                data = json.loads(body.decode("utf-8"))
            except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError):
                self._send_json(
                    400,
                    {"status": "error", "message": "Invalid JSON"},
                )
                return

            if not isinstance(data, dict) or "data" not in data:
                self._send_json(
                    400,
                    {"status": "error", "message": "No data received"},
                )
                return

            self._send_json(
                200,
                {
                    "status": "success",
                    "message": "Data received successfully.",
                },
            )

    return RequestHandler

