import requests
import json


def task_func(myString, API_KEY):
    """Extract URLs, geolocate their domains, and return the API responses."""
    urls = re.findall(r"https?://[^\s<>'\"]+", myString or "")
    domains = []

    for url in urls:
        url = url.rstrip(".,!?;:)]}")
        parsed_url = urllib.parse.urlparse(url)
        domain = parsed_url.hostname

        if domain and domain not in domains:
            domains.append(domain)

    result = {}

    for domain in domains:
        endpoint = f"https://pro.ip-api.com/json/{domain}"
        try:
            response = requests.get(endpoint, params={"key": API_KEY})
            if getattr(response, "status_code", 200) >= 400:
                result[domain] = None
            else:
                result[domain] = response.json()
        except (requests.RequestException, ValueError, json.JSONDecodeError):
            result[domain] = None

    return result

