import pandas as pd
import numpy as np
from sklearn.linear_model import LinearRegression

def task_func(start_date='2016-01-01', periods=13, freq='WOM-2FRI', sales_data=None):
    if not isinstance(periods, (int, np.integer)) or periods < 0:
        raise ValueError("periods must be a non-negative integer")

    data = None if sales_data is None else np.asarray(sales_data, dtype=float).reshape(-1)
    n_periods = periods if data is None else data.size

    pd.date_range(start=start_date, periods=n_periods, freq=freq)

    if n_periods == 0:
        return np.array([], dtype=float)

    if data is None:
        x = np.arange(n_periods, dtype=float)
        data = 100.0 + 5.0 * x + 10.0 * np.sin(2.0 * np.pi * x / 12.0)

    if not np.all(np.isfinite(data)):
        raise ValueError("sales_data must contain only finite numeric values")

    time_indices = np.arange(n_periods, dtype=float).reshape(-1, 1)
    future_indices = np.arange(n_periods, 2 * n_periods, dtype=float).reshape(-1, 1)

    model = LinearRegression()
    model.fit(time_indices, data)

    return np.asarray(model.predict(future_indices), dtype=float)

import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    pattern = directory_path.rstrip("/\\") + "/*.docx"
    files = []
    seen = set()

    for file_path in glob.glob(pattern) + glob.glob(
        directory_path.rstrip("/\\") + "/*.DOCX"
    ):
        if file_path not in seen:
            files.append(file_path)
            seen.add(file_path)

    def protect_text_parts(part, visited):
        part_id = id(part)
        if part_id in visited:
            return
        visited.add(part_id)

        element = getattr(part, "element", None)
        if element is not None:
            for node in element.iter():
                tag = getattr(node, "tag", "")
                local_name = tag.rsplit("}", 1)[-1]
                if local_name in {"t", "delText", "instrText", "delInstrText"}:
                    if node.text is not None:
                        node.text = re.sub(r'"', r'\\"', node.text)

        for relationship in getattr(part, "rels", {}).values():
            try:
                target_part = relationship.target_part
            except (AttributeError, KeyError):
                continue
            protect_text_parts(target_part, visited)

    for file_path in files:
        document = Document(file_path)
        protect_text_parts(document.part, set())
        document.save(file_path)

    return len(files)

import itertools
import math

def task_func(x):
    """Return a non-empty subsequence of keys with minimum total value."""
    if not x:
        return []

    items = list(x.items())
    best_sequence = []
    best_total = math.inf

    for size in range(1, len(items) + 1):
        for subsequence in itertools.combinations(items, size):
            total = sum(value for _, value in subsequence)
            if total < best_total:
                best_total = total
                best_sequence = [key for key, _ in subsequence]

    return best_sequence

