import os


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    regex = re.compile(pattern)
    hashes = {}

    for root, _, files in os.walk(directory):
        for filename in files:
            file_path = os.path.join(root, filename)
            normalized_path = file_path.replace(os.sep, "\\")

            if not (regex.search(file_path) or regex.search(normalized_path)):
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            hashes[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return hashes

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.text
        json.loads(data)

        name_pattern = re.compile(
            r'"name"\s*:\s*"((?:\\.|[^"\\])*)"'
        )
        names = []

        bracket_depth = 0
        in_string = False
        escaped = False
        depths = [0] * len(data)

        for index, char in enumerate(data):
            depths[index] = bracket_depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)

        for match in name_pattern.finditer(data):
            if depths[match.start()] > 0:
                continue

            name = json.loads(f'"{match.group(1)}"')
            if not (name.startswith("[") and name.endswith("]")):
                names.append(name)

        return names
    except Exception:
        return "Invalid url input"

