import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    repeated_data = data * repetitions
    frequencies = {}

    for item in repeated_data:
        frequencies[item] = frequencies.get(item, 0) + 1

    try:
        modes = sorted(
            item for item, count in frequencies.items()
            if count == max(frequencies.values())
        )
    except TypeError:
        modes = sorted(
            (item for item, count in frequencies.items()
             if count == max(frequencies.values())),
            key=lambda item: (type(item).__name__, repr(item)),
        )

    return {
        "mode": np.array(modes),
        "count": np.array([frequencies[item] for item in modes], dtype=int),
    }

import numpy as np
import pandas as pd


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    def is_numeric(value):
        return isinstance(value, (int, float, np.integer, np.floating)) and not isinstance(
            value, (bool, np.bool_)
        )

    if not isinstance(products, list) or not all(isinstance(product, str) for product in products):
        raise TypeError("products must be a list of strings")

    if not isinstance(n_samples, (int, np.integer)) or isinstance(n_samples, (bool, np.bool_)) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    for value in (sales_lower, sales_upper, profit_margin_min, profit_margin_max):
        if not is_numeric(value):
            raise TypeError("Sales and profit margin bounds must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    if profit_margin_min > profit_margin_max:
        raise ValueError("profit_margin_min cannot be greater than profit_margin_max")

    if not products:
        return pd.DataFrame(columns=["Product", "Total Sales", "Total Profit"])

    rng = np.random.default_rng(random_seed)
    sampled_products = rng.choice(products, size=n_samples)

    if float(sales_lower).is_integer() and float(sales_upper).is_integer():
        sales = rng.integers(
            int(sales_lower),
            int(sales_upper) + 1,
            size=n_samples,
        )
    else:
        sales = rng.uniform(sales_lower, sales_upper, size=n_samples)

    profit_margins = rng.uniform(
        profit_margin_min,
        profit_margin_max,
        size=n_samples,
    )
    profit = sales * profit_margins

    report = pd.DataFrame(
        {
            "Product": sampled_products,
            "Sales": sales,
            "Profit": profit,
        }
    )

    return (
        report.groupby("Product", as_index=False)
        .agg({"Sales": "sum", "Profit": "sum"})
        .rename(columns={"Sales": "Total Sales", "Profit": "Total Profit"})
        .sort_values("Total Profit", ascending=False, ignore_index=True)
    )

