def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the provided DataFrame.")
    if N <= 1:
        raise ValueError("N must be greater than 1.")

    differences = [
        (abs(a - b), index)
        for index, (a, b) in enumerate(zip(df[col1], df[col2]))
    ]

    selected = heapq.nlargest(N, differences, key=lambda item: item[0])
    indices = [index for _, index in selected]

    values1 = [df[col1].iloc[index] for index in indices]
