                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError(f"Invalid timestamp: {timestamp}") from exc

            entries.append({
                "Type": message_type.strip(),
                "Timestamp": timestamp,
                "Message": message,
            })

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = os.path.splitext(log_file)[0] + ".csv"
    pd.DataFrame(entries, columns=["Type", "Timestamp", "Message"]).to_csv(
        output_file,
        index=False,
    )

    return output_file

