# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """Retrieve API data, convert it to a DataFrame, and plot correlations."""
    try:
        if not isinstance(url, str) or not url.strip():
            raise ValueError("URL must be a non-empty string")

        parsed_url = urlparse(url)
        if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
            raise ValueError("Invalid URL")

        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS
        )
        response.raise_for_status()

        payload = response.json()
        if payload is None or payload == [] or payload == {}:
            raise ValueError("The API returned empty data")

        if isinstance(payload, dict):
            for key in ("data", "results", "items", "records"):
                if key in payload:
                    payload = payload[key]
                    break

            if isinstance(payload, dict):
                if all(isinstance(value, list) for value in payload.values()):
                    data = payload
                else:
                    data = [payload]
            else:
                data = payload
        else:
            data = payload

        if not isinstance(data, (list, tuple, dict)):
            raise ValueError("Invalid API data")

        dataframe = pd.DataFrame(data)

        if dataframe.empty or dataframe.shape[1] == 0:
            raise ValueError("The API returned empty data")

        numeric_data = dataframe.select_dtypes(include="number")
        if numeric_data.empty:
            raise ValueError("The data contains no numerical characteristics")

        correlation = numeric_data.corr()
        axes = sns.heatmap(correlation, annot=True, cmap="coolwarm")
        plt.show()

        return dataframe, axes

    except Exception as error:
        raise Exception(f"Unable to retrieve or process API data: {error}") from error

