from collections import Counter


def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Specified directory does not exist: {directory}")

    counts = Counter({extension: 0 for extension in extensions})

    for path in glob.iglob(os.path.join(directory, "**", "*"), recursive=True):
        if os.path.isfile(path):
            filename = os.path.basename(path)
            for extension in counts:
                if filename.endswith(extension):
                    counts[extension] += 1

    if not keep_zero:
        counts += Counter()

    return counts

