    if step_delta <= pd.Timedelta(0):
        raise ValueError("step must be positive.")

    timestamps = []
    current = start
    while current <= end:
        timestamps.append(current.to_pydatetime())
        current += step_delta

    rng = np.random.default_rng(random_seed)

    seconds = np.array([timestamp.timestamp() for timestamp in timestamps])
    noise = rng.normal(0.0, 0.01, size=(len(timestamps), 3))

    data = {
        columns[0]: timestamps,
        columns[1]: np.sin(seconds) + noise[:, 0],
        columns[2]: np.cos(seconds) + noise[:, 1],
        columns[3]: np.tan(seconds) + noise[:, 2],
        columns[4]: rng.choice(sensor_statuses, size=len(timestamps)),
    }

    return pd.DataFrame(data, columns=columns)

