def task_func(l1, l2, THRESHOLD=0.5):
    combined = []
    sentinel = object()

    for first, second in zip_longest(l1, l2, fillvalue=sentinel):
        if first is not sentinel and isinstance(first, numbers.Number) and not isinstance(first, bool):
            combined.append(first)
        if second is not sentinel and isinstance(second, numbers.Number) and not isinstance(second, bool):
