import pandas as pd
import os


def task_func(f_list, file_path):
    if not isinstance(f_list, list) or not f_list:
        raise ValueError("f_list must be a non-empty list of functions")

    if not all(inspect.isfunction(func) for func in f_list):
        raise ValueError("f_list must contain only functions")

    try:
        path = os.fspath(file_path)
        if not path or (isinstance(path, str) and "\x00" in path) or (
            isinstance(path, bytes) and b"\x00" in path
        ):
            raise ValueError("file_path is not a valid path")
    except (TypeError, ValueError) as exc:
        raise ValueError("file_path is not a valid path") from exc

    rows = []

    for func in f_list:
        try:
            signature = inspect.signature(func)
        except (TypeError, ValueError) as exc:
            raise ValueError("Unable to inspect function") from exc

        defaults = {
            name: parameter.default
            for name, parameter in signature.parameters.items()
            if parameter.default is not inspect.Parameter.empty
        }

        annotations = {
            name: parameter.annotation
            for name, parameter in signature.parameters.items()
            if parameter.annotation is not inspect.Parameter.empty
        }

        if signature.return_annotation is not inspect.Signature.empty:
            annotations["return"] = signature.return_annotation

        rows.append(
            {
                "Function Name": func.__name__,
                "Number of Arguments": len(signature.parameters),
                "Defaults": defaults,
                "Annotations": annotations,
                "Is Lambda": func.__name__ == "<lambda>",
            }
        )

    try:
        pd.DataFrame(rows).to_csv(path, index=False)
    except (OSError, IOError) as exc:
        raise IOError("Error writing to the specified file path") from exc

