# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]


def task_func(rows, columns):
    """Generate a DataFrame containing randomly typed column data."""
    if not isinstance(rows, (int, np.integer)) or isinstance(rows, bool):
        raise TypeError("rows must be a non-negative integer")
    if not isinstance(columns, (int, np.integer)) or isinstance(columns, bool):
        raise TypeError("columns must be a non-negative integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    def random_value(data_type):
        if data_type is str:
            return "".join(choice("abcdefghijklmnopqrstuvwxyz") for _ in range(5))
        if data_type is int:
            return int(np.random.randint(0, 10))
        if data_type is float:
            return float(np.random.randint(0, 10))
        if data_type is list:
            length = int(np.random.randint(1, 6))
            return [int(np.random.randint(0, 10)) for _ in range(length)]
        if data_type is tuple:
            length = int(np.random.randint(1, 6))
            return tuple(int(np.random.randint(0, 10)) for _ in range(length))
        if data_type is dict:
            length = int(np.random.randint(1, 6))
            result = {}
            while len(result) < length:
                result[int(np.random.randint(0, 10))] = int(
                    np.random.randint(0, 10)
                )
            return result
        if data_type is set:
            size = int(np.random.randint(1, 6))
            return set(np.random.choice(10, size=size, replace=False).tolist())
        raise ValueError(f"Unsupported data type: {data_type}")

    data = {}
    for column_index in range(columns):
        data_type = choice(DATA_TYPES)
        data[f"col{column_index}"] = [
            random_value(data_type) for _ in range(rows)
        ]

    return pd.DataFrame(data, index=range(rows))

