import re
import os
import glob


def task_func(dir_path: str) -> list:
    files = [
        path for path in glob.glob(os.path.join(dir_path, "*"))
        if os.path.isfile(path)
    ]

    renames = []
    targets = set()

    for path in files:
        old_name = os.path.basename(path)
        new_name = re.sub(r"[^A-Za-z0-9]", "", old_name)

        if not new_name:
            raise ValueError(f"Filename '{old_name}' becomes empty")

        target = os.path.join(dir_path, new_name)

        if target in targets:
            raise FileExistsError(f"Multiple files would be renamed to '{new_name}'")

        if os.path.exists(target) and os.path.abspath(target) != os.path.abspath(path):
            raise FileExistsError(f"Target file already exists: '{new_name}'")

        targets.add(target)
        renames.append((path, target, new_name))

    for source, target, _ in renames:
        if os.path.abspath(source) != os.path.abspath(target):
            os.rename(source, target)

    return [new_name for _, _, new_name in renames]

