import pandas as pd
import numpy as np
import statsmodels.api as sm


def task_func(
    array: list, random_seed: int = 0
) -> (pd.DataFrame, sm.regression.linear_model.RegressionResultsWrapper):
    if not isinstance(array, list) or not array:
        raise ValueError("array must be a non-empty 2D list.")

    if not all(isinstance(row, list) and len(row) == 5 for row in array):
        raise ValueError("Each row must be a list containing exactly 5 values.")

    if isinstance(random_seed, bool) or not isinstance(
        random_seed, (int, np.integer)
    ):
        raise TypeError("random_seed must be an integer.")

    df = pd.DataFrame(array, columns=["A", "B", "C", "D", "Response"])

    if not all(pd.api.types.is_numeric_dtype(df[column]) for column in df.columns):
        raise ValueError("All values in array must be numeric.")

    if not np.isfinite(df.to_numpy(dtype=float)).all():
        raise ValueError("array must not contain NaN or infinite values.")

    np.random.seed(int(random_seed))

    independent_variables = sm.add_constant(df[["A", "B", "C", "D"]])
    dependent_variable = df["Response"]
    results = sm.OLS(dependent_variable, independent_variables).fit()

    return df, results

import json
import csv


def task_func(json_file, csv_file):
    with open(json_file, "r", encoding="utf-8") as file:
        data = json.load(file)

    if isinstance(data, dict):
        rows = [data]
    elif isinstance(data, list):
        rows = data
    else:
        raise ValueError("JSON must contain an object or a list of objects.")

    if not all(isinstance(row, dict) for row in rows):
        raise ValueError("All JSON records must be objects.")

    fieldnames = []
    for row in rows:
        for key in row:
            if key not in fieldnames:
                fieldnames.append(key)

    with open(csv_file, "w", encoding="utf-8", newline="") as file:
        writer = csv.DictWriter(file, fieldnames=fieldnames)
        if fieldnames:
            writer.writeheader()
            writer.writerows(rows)

    return csv_file

