import pandas as pd
import pytz


def task_func(articles, timezone):
    required_keys = {"published_time", "category"}

    if not isinstance(articles, list) or not all(
        isinstance(article, dict) for article in articles
    ):
        raise TypeError("articles must be a list of dictionaries")

    if not articles:
        raise ValueError("articles must not be empty")

    if any(set(article.keys()) != required_keys for article in articles):
        raise ValueError(
            "Each article must contain exactly 'published_time' and 'category' keys"
        )

    target_timezone = pytz.timezone(timezone)
    data = pd.DataFrame(articles)

    timestamps = pd.to_datetime(data["published_time"], utc=True)
    data["publication_hour"] = (
        timestamps.dt.tz_convert(target_timezone).dt.hour
    )

    result = (
        data.groupby("category")["publication_hour"]
        .agg(count="count", mean="mean", min="min", max="max")
    )

    return result

