import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"


def task_func(json_str):
    data = json.loads(json_str)

    email_pattern = re.compile(
        r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@"
        r"[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+"
    )

    def remove_none(value):
        if isinstance(value, dict):
            return {
                key: remove_none(item)
                for key, item in value.items()
                if item is not None
            }
        if isinstance(value, list):
            return [
                remove_none(item)
                for item in value
                if item is not None
            ]
        return value

    def collect_values(value, counter):
        if isinstance(value, dict):
            for item in value.values():
                collect_values(item, counter)
        elif isinstance(value, list):
            for item in value:
                collect_values(item, counter)
        elif value is not None:
            counter[value] += 1

    def replace_emails(value):
        if isinstance(value, dict):
            return {
                key: replace_emails(item)
                for key, item in value.items()
            }
        if isinstance(value, list):
            return [replace_emails(item) for item in value]
        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)
        return value

    data = remove_none(data)
    value_counts = Counter()
    collect_values(data, value_counts)
    data = replace_emails(data)

    return {
        "data": data,
        "value_counts": value_counts,
    }

