import numpy as np
import math

def task_func(ax, num_turns):
    if not isinstance(num_turns, (int, float, np.number)):
        raise TypeError("num_turns must be numeric")
    if not math.isfinite(float(num_turns)) or num_turns < 0:
        raise ValueError("num_turns must be a finite non-negative number")

    num_turns = float(num_turns)

    if num_turns == 0:
        theta = np.array([0.0])
        radius = np.array([0.0])
    else:
        points = max(2, int(math.ceil(1000 * num_turns)) + 1)
        theta = np.linspace(0.0, 2.0 * math.pi * num_turns, points)
        radius = theta / (2.0 * math.pi)

    ax.plot(theta, radius)

    tick_interval = math.radians(45.0 * num_turns)
    if tick_interval > 0:
        tick_angles = np.arange(0.0, 2.0 * math.pi, tick_interval)
    else:
        tick_angles = np.array([0.0])

    ax.set_xticks(tick_angles)
    return ax

