import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    keys = [
        key for key in mapping
        if isinstance(key, str) and key
    ]

    if not keys:
        return result

    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(
            re.escape(key) for key in sorted(keys, key=len, reverse=True)
        ) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if not isinstance(value, str):
            return value

        return pattern.sub(
            lambda match: str(mapping[match.group(0)]),
            value
        )

    for column in result.columns:
        result[column] = result[column].map(replace_acronyms)

    return result

