import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0 or not vocabulary:
        raise ValueError

    patterns = []
    for target in target_words:
        parts = re.split(r"\s+", str(target).strip().lower())
        if parts and any(parts):
            pattern = r"(?<!\w)" + r"\s+".join(
                re.escape(part) for part in parts
            ) + r"(?!\w)"
            patterns.append(pattern)

    matcher = re.compile("|".join(patterns)) if patterns else None
    sentences = []

    for _ in range(n_sentences):
        sentence = " ".join(random.choices(vocabulary, k=10)).lower()
        if matcher:
            sentence = matcher.sub(
                lambda match: re.sub(r"\s+", "_", match.group(0)),
                sentence,
            )
        sentences.append(sentence)

    return sentences

