import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    start_time = datetime.now()
    deadline = start_time + timedelta(seconds=run_duration)
    server_socket = None
    clients = set()
    message_queues = {}
    send_buffers = {}

    def close_client(client_socket):
        clients.discard(client_socket)
        message_queues.pop(client_socket, None)
        send_buffers.pop(client_socket, None)
        try:
            client_socket.close()
        except OSError:
            pass

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        while True:
            remaining = (deadline - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            read_sockets = [server_socket, *clients]
            write_sockets = [
                client
                for client in clients
                if client in send_buffers
                or not message_queues[client].empty()
            ]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    read_sockets,
                    write_sockets,
                    exceptional_sockets,
                    remaining,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    try:
                        client_socket, _ = server_socket.accept()
                        client_socket.setblocking(False)
                        clients.add(client_socket)
                        message_queues[client_socket] = queue.Queue()
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client_socket in exceptional:
                if client_socket is not server_socket:
                    close_client(client_socket)

            for client_socket in readable:
                if client_socket not in clients:
                    continue

                try:
                    data = client_socket.recv(buffer_size)
                    if not data:
                        close_client(client_socket)
                        continue

                    timestamp = datetime.now().isoformat().encode("utf-8")
                    message_queues[client_socket].put(data + timestamp)
                except (BlockingIOError, InterruptedError):
                    continue
                except OSError:
                    close_client(client_socket)

            for client_socket in writable:
                if client_socket not in clients:
                    continue

                try:
                    if client_socket not in send_buffers:
                        send_buffers[client_socket] = (
                            message_queues[client_socket].get_nowait()
                        )

                    pending = send_buffers[client_socket]
                    sent = client_socket.send(pending)

                    if sent == 0:
                        close_client(client_socket)
                    elif sent == len(pending):
                        del send_buffers[client_socket]
                    else:
                        send_buffers[client_socket] = pending[sent:]
                except queue.Empty:
                    send_buffers.pop(client_socket, None)
                except (BlockingIOError, InterruptedError):
                    continue
                except OSError:
                    close_client(client_socket)

    except OSError as error:
        elapsed = (datetime.now() - start_time).total_seconds()
        return f"Server failed after {elapsed:.2f} seconds: {error}"

    finally:
        for client_socket in list(clients):
            close_client(client_socket)
        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Server operated for {elapsed:.2f} seconds."

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
           latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
           other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
           rng_seed=None):
    if not isinstance(start_year, int) or not isinstance(end_year, int):
        raise TypeError("start_year and end_year must be integers")
    if start_year < 0 or end_year < start_year:
        raise ValueError("Invalid year range")
    if not latin_names and not other_names:
        raise ValueError("At least one name must be provided")

    def fix_encoding(value):
        if isinstance(value, bytes):
            value = value.decode("utf-8", errors="replace")

        value = str(value)
        if re.search(r"[ÃÂâ]", value):
            try:
                repaired = codecs.decode(value.encode("latin1"), "utf-8")
                if repaired:
                    return repaired
            except (UnicodeEncodeError, UnicodeDecodeError):
                pass
        return value

    def is_leap_year(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_year(year):
        return 366 if is_leap_year(year) else 365

    def date_from_offset(year, offset):
        month_lengths = [
            31, 29 if is_leap_year(year) else 28, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31
        ]
        month = 1
        while offset >= month_lengths[month - 1]:
            offset -= month_lengths[month - 1]
            month += 1
        day = offset + 1

        if year == 0:
            return f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
        return datetime.datetime(year, month, day)

    rng = np.random.RandomState(rng_seed)
    names = [fix_encoding(name) for name in latin_names + other_names]

    total_days = sum(days_in_year(year) for year in range(start_year, end_year + 1))
    offsets = rng.randint(0, total_days, size=100)

    birth_dates = []
    birth_years = []
    for offset in offsets:
        year = start_year
        while offset >= days_in_year(year):
            offset -= days_in_year(year)
            year += 1
        birth_dates.append(date_from_offset(year, int(offset)))
        birth_years.append(year)

    selected_names = rng.choice(names, size=100)

    data = {
        "ID": np.arange(1, 101),
        "Name": selected_names,
        "Date of Birth": birth_dates,
        "Email": [
            f"{name.lower()}{year}@{email_domain}"
            for name, year in zip(selected_names, birth_years)
        ],
    }

    return pd.DataFrame(data)

