import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    """Generate a synthetic sales series and decompose it."""

    if not isinstance(periods, (int, np.integer)) or periods <= 0:
        raise ValueError("periods must be a positive integer")

    model = str(model).lower()
    if model not in {"additive", "multiplicative"}:
        raise ValueError("model must be 'additive' or 'multiplicative'")

    index = pd.date_range(start=start_date, periods=periods, freq=freq)
    normalized_freq = str(freq).upper()

    if normalized_freq.startswith(("A", "Y")):
        seasonal_period = 1
    elif normalized_freq.startswith(("Q",)):
        seasonal_period = 4
    elif normalized_freq.startswith(("M",)):
        seasonal_period = 12
    elif normalized_freq.startswith(("W", "D")):
        seasonal_period = 7
    elif normalized_freq.startswith(("H",)):
        seasonal_period = 24
    else:
        seasonal_period = 12

    if seasonal_period < 2 or periods < 2 * seasonal_period:
        raise ValueError(
            "periods must contain at least two complete seasonal cycles"
        )

    time = np.arange(periods, dtype=float)
    trend = 100 + 2.5 * time
    seasonal = 1 + 0.15 * np.sin(2 * np.pi * time / seasonal_period)
    noise = np.random.default_rng(42).normal(0, 0.02, periods)

    if model == "multiplicative":
        sales = trend * seasonal * (1 + noise)
        sales = np.maximum(sales, np.finfo(float).eps)
    else:
        sales = trend + 15 * np.sin(2 * np.pi * time / seasonal_period) + noise * 10

    sales_series = pd.Series(sales, index=index, name="sales")
    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period,
        extrapolate_trend=False,
    )

    return {
        "trend": decomposition.trend,
        "seasonal": decomposition.seasonal,
        "residual": decomposition.resid,
    }

