import binascii
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


def task_func(hex_str):
    """Convert a hex string to bytes, count byte frequencies, and plot them."""
    if not isinstance(hex_str, str):
        raise ValueError("'hex_str' must be a valid hex string")

    normalized = hex_str

    if "\\x" in normalized:
        if not normalized.startswith("\\x"):
            raise ValueError("'hex_str' must be a valid hex string")

        parts = normalized.split("\\x")[1:]
        if any(len(part) != 2 for part in parts):
            raise ValueError("'hex_str' must be a valid hex string")

        normalized = "".join(parts)

    try:
        byte_data = binascii.unhexlify(normalized)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("'hex_str' must be a valid hex string") from exc

    if byte_data:
        values, frequencies = np.unique(
            np.frombuffer(byte_data, dtype=np.uint8),
            return_counts=True,
        )
    else:
        values = np.array([], dtype=np.uint8)
        frequencies = np.array([], dtype=np.int64)

    frequency_df = pd.DataFrame(
        {
            "Byte Value": values,
            "Frequency": frequencies,
        }
    )

    ax = frequency_df.plot(
        x="Byte Value",
        y="Frequency",
        kind="bar",
        legend=False,
    )
    ax.set_xlabel("Byte Value")
    ax.set_ylabel("Frequency")

    return frequency_df, ax

