import ssl
import os
import hashlib


def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    try:
        if buffer_size <= 0:
            raise ValueError("buffer_size must be greater than zero")

        secure_socket = ssl.wrap_socket(
            client_socket,
            server_side=True,
            certfile=cert_file,
            keyfile=key_file,
        )

        file_path = secure_socket.recv(buffer_size).decode("utf-8").strip()

        if not os.path.exists(file_path):
            response = "File not found"
        else:
            file_hash = hashlib.sha256()

            with open(file_path, "rb") as file:
                while chunk := file.read(buffer_size):
                    file_hash.update(chunk)

            response = file_hash.hexdigest()

        secure_socket.sendall(response.encode("utf-8"))
        return response

    except Exception as error:
        response = f"Error: {error}"

        try:
            secure_socket.sendall(response.encode("utf-8"))
        except Exception:
            pass

        return response

from random import shuffle, randint
import pandas as pd


def task_func(l, n_groups=5):
    """Return a shuffled, repeated Series with cyclically rotated strings."""
    if not isinstance(n_groups, int):
        raise TypeError("n_groups must be an integer")
    if n_groups < 0:
        raise ValueError("n_groups must be non-negative")

    items = list(l)
    shuffle(items)

    result = []
    for value in items * n_groups:
        if not value:
            result.append(value)
            continue

        n = randint(1, min(n_groups, len(value))) if n_groups else 0
        result.append(value[n:] + value[:n])

    return pd.Series(result)

