import pandas as pd
import folium
from geopy.geocoders import Photon

def task_func(dic):
    from collections.abc import Mapping
    from numbers import Real

    geolocator = Photon(user_agent="geoapiExercises")

    def is_coordinate(value):
        return (
            isinstance(value, (list, tuple))
            and len(value) >= 2
            and isinstance(value[0], Real)
            and isinstance(value[1], Real)
        )

    def make_records(data):
        if isinstance(data, pd.DataFrame):
            return data.to_dict("records")

        if isinstance(data, Mapping):
            keys = {str(key).lower(): key for key in data}

            if "latitude" in keys and "longitude" in keys:
                latitudes = data[keys["latitude"]]
                longitudes = data[keys["longitude"]]
                if isinstance(latitudes, (list, tuple)):
                    return [
                        {
                            "location": (lat, lon),
                            "label": str(i),
                        }
                        for i, (lat, lon) in enumerate(zip(latitudes, longitudes))
                    ]
                return [{"location": (latitudes, longitudes)}]

            for collection_key in ("locations", "addresses", "data"):
                if collection_key in keys:
                    values = data[keys[collection_key]]
                    if isinstance(values, Mapping):
                        return list(values.items())
                    return list(values)

            if "location" in keys or "address" in keys or "coordinates" in keys:
                return [data]

            return list(data.items())

        if isinstance(data, (list, tuple)):
            if is_coordinate(data):
                return [data]
            return list(data)

        return [data]

    def extract_location(item):
        label = None
        value = item

        if isinstance(item, Mapping):
            lowered = {str(key).lower(): key for key in item}

            label_key = next(
                (lowered[key] for key in ("label", "name", "title") if key in lowered),
                None,
            )
            if label_key is not None:
                label = item[label_key]

            if "latitude" in lowered and "longitude" in lowered:
                value = (
                    item[lowered["latitude"]],
                    item[lowered["longitude"]],
                )
            else:
                location_key = next(
                    (
                        lowered[key]
                        for key in ("location", "address", "coordinates", "coordinate")
                        if key in lowered
                    ),
                    None,
                )
                if location_key is not None:
                    value = item[location_key]
                elif label_key is not None:
                    value = next(
                        (v for k, v in item.items() if k != label_key),
                        None,
                    )

        elif isinstance(item, tuple) and len(item) == 2 and not is_coordinate(item):
            label, value = item

        return label, value

    resolved = []

    for index, item in enumerate(make_records(dic)):
        label, value = extract_location(item)

        if is_coordinate(value):
            latitude, longitude = float(value[0]), float(value[1])
        elif isinstance(value, str):
            location = geolocator.geocode(value)
            if location is None:
                continue
            latitude, longitude = location.latitude, location.longitude
            if label is None:
                label = value
        else:
            continue

        resolved.append(
            (
                latitude,
                longitude,
                str(label) if label is not None else f"Location {index + 1}",
            )
        )

    center = (
        [resolved[0][0], resolved[0][1]]
        if resolved
        else [0, 0]
    )
    fmap = folium.Map(location=center, zoom_start=2)

    for latitude, longitude, label in resolved:
        folium.Marker(
            location=[latitude, longitude],
            popup=label,
        ).add_to(fmap)

    return fmap

