import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if not isinstance(date_str, str):
        raise ValueError("date_str must follow the yyyy-mm-dd format.")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("date_str must follow the yyyy-mm-dd format.") from exc

    if requested_date.strftime("%Y-%m-%d") != date_str:
        raise ValueError("date_str must follow the yyyy-mm-dd format.")

    if requested_date.date() < datetime.now().date():
        raise ValueError("date_str must not refer to a past date.")

    def normalize_status(value):
        if isinstance(value, bool):
            return "Booked" if value else "Available"
        if value is None:
            return "Available"
        return str(value)

    def matches_date(value):
        if isinstance(value, datetime):
            return value.strftime("%Y-%m-%d") == date_str
        return str(value)[:10] == date_str

    def find_status(source, room):
        if isinstance(booking_data, pd.DataFrame):
            records = booking_data.to_dict("records")
            return find_status(records, room)

        if isinstance(source, dict):
            if date_str in source:
                return normalize_status(source[date_str])

            if "date" in source or "booking_date" in source:
                record_date = source.get("date", source.get("booking_date"))
                if matches_date(record_date):
                    return normalize_status(
                        source.get("status", source.get("booking_status", "Booked"))
                    )
                return "Available"

            if "status" in source or "booking_status" in source:
                return normalize_status(
                    source.get("status", source.get("booking_status"))
                )

            return "Available"

        if isinstance(source, (list, tuple, set)):
            for item in source:
                if isinstance(item, dict):
                    item_room = item.get("room", item.get("room_name"))
                    if item_room is not None and item_room != room:
                        continue

                    item_date = item.get("date", item.get("booking_date"))
                    if item_date is None or matches_date(item_date):
                        return normalize_status(
                            item.get(
                                "status",
                                item.get("booking_status", "Booked"),
                            )
                        )
                elif matches_date(item):
                    return "Booked"
            return "Available"

        if source is None:
            return "Available"

        return normalize_status(source)

    report = []
    for room in ROOMS:
        source = None

        if isinstance(booking_data, dict):
            if room in booking_data:
                source = booking_data[room]
            elif date_str in booking_data and isinstance(booking_data[date_str], dict):
                source = booking_data[date_str].get(room)
        elif isinstance(booking_data, pd.DataFrame):
            source = booking_data
        elif isinstance(booking_data, (list, tuple)):
            source = booking_data

        report.append({"Room": room, "Status": find_status(source, room)})

    status_df = pd.DataFrame(report)

    statuses = list(dict.fromkeys(status_df["Status"]))
    status_codes = {status: index + 1 for index, status in enumerate(statuses)}

    fig, ax = plt.subplots()
    ax.bar(
        status_df["Room"],
        status_df["Status"].map(status_codes),
        color="steelblue",
    )
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_title(f"Room Booking Statuses for {date_str}")
    ax.set_yticks(list(status_codes.values()))
    ax.set_yticklabels(list(status_codes.keys()))

    return status_df, ax

