import os
from pathlib import Path
import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source_path = Path(source_directory)

    if not source_path.exists():
        raise FileNotFoundError(source_directory)

    target_path = Path(target_directory)
    source_absolute = source_path.resolve()
    target_absolute = target_path.resolve()

    files = glob.glob(
        os.path.join(str(source_path), "**", "*"),
        recursive=True,
    )

    extensions = {".txt", ".docx", ".xlsx", ".csv"}
    moved_count = 0

    target_path.mkdir(parents=True, exist_ok=True)

    for file_path in files:
        file = Path(file_path)

        if not file.is_file() or file.suffix.lower() not in extensions:
            continue

        try:
            if os.path.commonpath((str(file.resolve()), str(target_absolute))) == str(
                target_absolute
            ):
                continue
        except ValueError:
            pass

        destination = target_path / file.name

        if destination.exists():
            counter = 1
            while True:
                candidate = (
                    target_path
                    / f"{file.stem}-{counter}{file.suffix}"
                )
                if not candidate.exists():
                    destination = candidate
                    break
                counter += 1

        shutil.move(str(file), str(destination))
        moved_count += 1

    return moved_count

