import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    """Return absolute paths of files containing a case-insensitive regex match."""
    if not os.path.isdir(directory):
        return []

    if isinstance(extensions, str):
        extensions = [extensions]

    normalized_extensions = []
    for extension in extensions or []:
        extension = str(extension).lower()
        if extension and not extension.startswith("."):
            extension = "." + extension
        if extension:
            normalized_extensions.append(extension)

    regex = re.compile(pattern, re.IGNORECASE)
    search_pattern = os.path.join(os.path.abspath(directory), "**", "*")
    matching_files = []

    for file_path in glob.iglob(search_pattern, recursive=True):
        if not os.path.isfile(file_path):
            continue

        if normalized_extensions and not any(
            file_path.lower().endswith(extension)
            for extension in normalized_extensions
        ):
            continue

        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    matching_files.append(os.path.abspath(file_path))
        except (OSError, UnicodeError):
            continue

    return sorted(set(matching_files))

